const $=id=>document.getElementById(id);let candles=[],source='',isDemo=false,isImport=false,busy=false,revision=0,setup=null,journal=[];try{journal=JSON.parse(localStorage.getItem('signal-journal')||'[]')}catch{}const fmt=n=>Number(n).toLocaleString(undefined,{maximumFractionDigits:5});
const provider=document.createElement('section');provider.className='toolbar';provider.style.marginTop='16px';provider.innerHTML='<div><label for="feed">Data connection</label><select id="feed"><option value="kraken">Crypto · Kraken</option><option value="twelve">All markets · Twelve Data</option></select></div><div><label for="symbol">Forex, gold, stock or index symbol</label><input id="symbol" placeholder="EUR/USD, XAU/USD, AAPL, SPX" value="EUR/USD"></div><div><label for="key">Twelve Data API key · kept in memory</label><input id="key" type="password" autocomplete="off" placeholder="Your provider API key"></div>';document.querySelector('.toolbar').after(provider);
function ema(a,p){let e=a[0];return a.map((v,i)=>e=i?e+(v-e)*2/(p+1):v)}
function indicators(a){let c=a.map(x=>x.c),fast=ema(c,9),slow=ema(c,21),g=0,l=0,atr=0;for(let i=1;i<a.length;i++){let d=c[i]-c[i-1],tr=Math.max(a[i].h-a[i].l,Math.abs(a[i].h-c[i-1]),Math.abs(a[i].l-c[i-1]));if(i<=14){g+=Math.max(d,0)/14;l+=Math.max(-d,0)/14;atr+=tr/14}else{g=(g*13+Math.max(d,0))/14;l=(l*13+Math.max(-d,0))/14;atr=(atr*13+tr)/14}}return {fast,slow,rsi:!l?g?100:50:100-100/(1+g/l),atr}}
function evaluate(a){let q=indicators(a),c=a.at(-1).c,f=q.fast.at(-1),s=q.slow.at(-1),buy=f>s&&c>s&&q.rsi>50&&q.rsi<70,sell=f<s&&c<s&&q.rsi>30&&q.rsi<50;return {...q,c,f,s,side:buy?'BUY':sell?'SELL / EXIT':'WAIT'}}
function valid(a){if(a.length<60)throw Error('At least 60 completed candles are required.');for(let i=0;i<a.length;i++){let x=a[i];if(![x.t,x.o,x.h,x.l,x.c,x.v].every(Number.isFinite)||x.l<=0||x.v<0||x.h<Math.max(x.o,x.c,x.l)||x.l>Math.min(x.o,x.c)||i&&x.t<=a[i-1].t)throw Error('Invalid OHLC values, duplicate timestamps, or unsorted candles.')}}
function render(){if(!candles.length)return;const q=evaluate(candles),last=candles.at(-1),stale=!isDemo&&!isImport&&Date.now()-last.t>Number($('interval').value)*60000*2.2;setup={...q,side:stale?'WAIT':q.side};$('market').firstChild.textContent=source+' ';$('mode').textContent=isDemo?'DEMO':isImport?'IMPORTED':stale?'STALE':'LIVE FEED';$('price').textContent=fmt(q.c);$('signal').textContent=setup.side;$('signal').style.color=setup.side==='BUY'?'#96e4c0':setup.side==='SELL / EXIT'?'#fa9a9c':'#edbd67';$('signalnote').textContent=stale?'Feed is stale or the market is closed. Wait for fresh data.':isDemo?'Illustrative demo only. Do not trade on this data.':isImport?'Historical CSV analysis. Confirm freshness before acting.':setup.side==='WAIT'?'No complete setup. Wait for the rules to align.':'Rules align on the last completed candle. Confirm your entry manually.';$('reasons').replaceChildren();[['Trend',q.f>q.s?'EMA 9 > EMA 21':'EMA 9 ≤ EMA 21'],['Price',q.c>q.s?'Above EMA 21':'At / below EMA 21'],['Momentum','RSI '+q.rsi.toFixed(1)]].forEach(([a,b])=>{let d=document.createElement('div');d.className='reason';let l=document.createElement('span'),r=document.createElement('b');l.textContent=a;r.textContent=b;d.append(l,r);$('reasons').append(d)});$('rsi').textContent=q.rsi.toFixed(1);$('trend').textContent=q.f>q.s?'Bullish':'Bearish';$('atr').textContent=fmt(q.atr);$('closed').textContent=new Date(last.t).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});$('closed').title=new Date(last.t).toLocaleString();draw(q);plan()}
function draw(q){let a=candles.slice(-70),offset=candles.length-a.length,min=Math.min(...a.map(x=>x.l),...q.slow.slice(-70)),max=Math.max(...a.map(x=>x.h),...q.slow.slice(-70)),span=max-min||1,y=v=>275-(v-min)/span*240,x=i=>20+i*11.5;let svg='';for(let j=0;j<5;j++){let v=min+span*j/4;svg+=`<line x1="15" x2="825" y1="${y(v)}" y2="${y(v)}" stroke="#27313a"/><text x="835" y="${y(v)+4}" fill="#899ba7" font-size="10">${fmt(v)}</text>`}a.forEach((v,i)=>{let color=v.c>=v.o?'#96e4c0':'#e98d97';svg+=`<line x1="${x(i)}" x2="${x(i)}" y1="${y(v.h)}" y2="${y(v.l)}" stroke="${color}"/><rect x="${x(i)-3}" y="${Math.min(y(v.o),y(v.c))}" width="6" height="${Math.max(1,Math.abs(y(v.o)-y(v.c)))}" fill="${color}"/>`});[q.fast,q.slow].forEach((line,j)=>svg+=`<polyline points="${line.slice(offset).map((v,i)=>x(i)+','+y(v)).join(' ')}" fill="none" stroke="${j?'#edbd67':'#b6a6ff'}" stroke-width="1.6"/>`);$('chart').innerHTML=svg;$('range').textContent=new Date(a[0].t).toLocaleDateString()+' → '+new Date(a.at(-1).t).toLocaleString()}
function plan(){if(!setup)return;let b=+$('balance').value,r=+$('risk').value,m=+$('stop').value,rr=+$('rr').value;if(!(b>0&&r>0&&r<=100&&m>0&&rr>0&&setup.atr>0)){$('plan').textContent='Enter positive values; risk must be at most 100%.';return}let distance=setup.atr*m,short=setup.side==='SELL / EXIT',stop=setup.c+(short?distance:-distance),target=setup.c+(short?-1:1)*distance*rr;if(stop<=0||target<=0){$('plan').textContent='Stop or target is invalid. Reduce the ATR multiplier.';return}let units=b*r/100/distance;setup.plan={stop,target,units,risk:b*r/100};$('plan').innerHTML=[['Reference close',fmt(setup.c)],['Stop',fmt(stop)],['Target',fmt(target)],['Units',fmt(units)],['Risk · USD',fmt(b*r/100)]].map(([k,v])=>`<div><small>${k}</small><b>${v}</b></div>`).join(' ');if(setup.side==='WAIT')$('plan').insertAdjacentHTML('beforeend','<div class="muted">WAIT: long scenario for planning only; no entry signal.</div>');if(units*setup.c>b)$('plan').insertAdjacentHTML('beforeend','<div class="muted">Position exceeds account balance. Reduce units to match available funds.</div>')}
function invalidate(){revision++;candles=[];setup=null;$('signal').textContent='WAIT';$('signalnote').textContent='Selection changed. Refresh data to analyse.';$('mode').textContent='NOT LOADED';$('price').textContent='—';$('chart').innerHTML='';$('reasons').replaceChildren();for(let id of ['rsi','trend','atr','closed'])$(id).textContent='—';$('plan').textContent='Refresh data for this selection.'}
async function load(){if(busy)return;busy=true;let rev=++revision;invalidate();rev=revision;$('refresh').disabled=true;$('status').textContent='Fetching completed candles…';try{let a,label;if($('feed').value==='kraken'){let res=await fetch('https://api.kraken.com/0/public/OHLC?pair='+encodeURIComponent($('pair').value)+'&interval='+$('interval').value,{signal:AbortSignal.timeout(15000)});if(!res.ok)throw Error('Market feed HTTP '+res.status);let j=await res.json();if(j.error?.length)throw Error(j.error.join(', '));let rows=Object.values(j.result).find(Array.isArray);if(!rows)throw Error('No candle data returned');a=rows.slice(0,-1).map(r=>({t:+r[0]*1000,o:+r[1],h:+r[2],l:+r[3],c:+r[4],v:+r[6]}));label=$('pair').selectedOptions[0].textContent.split(' · ')[1]}else{if(!$('key').value.trim())throw Error('Enter a Twelve Data API key for forex, gold, stocks and indices. Coverage depends on your plan; CSV import is also available.');let intervals={15:'15min',60:'1h',240:'4h',1440:'1day'},url=new URL('https://api.twelvedata.com/time_series');Object.entries({symbol:$('symbol').value.trim(),interval:intervals[$('interval').value],outputsize:200,timezone:'UTC',apikey:$('key').value.trim()}).forEach(([k,v])=>url.searchParams.set(k,v));let res=await fetch(url,{signal:AbortSignal.timeout(15000)}),j=await res.json();if(j.status==='error'||!j.values)throw Error(j.message||'No data for that symbol or plan');a=j.values.map(r=>({t:Date.parse(r.datetime.replace(' ','T')+(r.datetime.includes('T')?'':'Z')),o:+r.open,h:+r.high,l:+r.low,c:+r.close,v:+(r.volume||0)})).sort((a,b)=>a.t-b.t).filter(r=>r.t+Number($('interval').value)*60000<=Date.now());label=$('symbol').value.trim()}valid(a);if(rev!==revision)return;candles=a;source=label;isDemo=isImport=false;render();$('status').textContent='● '+($('feed').value==='kraken'?'Kraken':'Twelve Data')+' · '+a.length+' completed candles · updated '+new Date().toLocaleTimeString()+' · refreshes every 60s while this page is open.'}catch(e){if(rev===revision){$('status').textContent='Data unavailable: '+e.message+' No active signal. Try CSV import or Explore demo.';$('signalnote').textContent='Data unavailable. No active signal.'}}finally{busy=false;$('refresh').disabled=false}}
$('refresh').onclick=load;['pair','interval','feed','symbol','key'].forEach(id=>$(id).onchange=invalidate);['balance','risk','stop','rr'].forEach(id=>$(id).oninput=plan);
$('demo').onclick=()=>{invalidate();let p=100,a=[],step=Number($('interval').value)*60000;for(let i=0;i<180;i++){let o=p;p+=Math.sin(i*.71)*.65+Math.cos(i*.17)*.35+.06;a.push({t:Math.floor(Date.now()/step)*step-(180-i)*step,o,c:p,h:Math.max(o,p)+.5,l:Math.min(o,p)-.5,v:100+i})}candles=a;source='DEMO / USD';isDemo=true;isImport=false;$('status').textContent='DEMO · Generated sample data. Automatic refresh paused. Click Refresh data to return to your feed.';render()};
$('file').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{let lines=(await file.text()).trim().split(/\r?\n/),head=lines.shift().toLowerCase().split(',').map(x=>x.trim()),required=['time','open','high','low','close'];if(!required.every(k=>head.includes(k)))throw Error('CSV header must contain time,open,high,low,close and optional volume. Use Unix seconds, milliseconds or ISO timestamps with a timezone.');let rows=lines.filter(x=>x.trim()).map(line=>{let v=line.split(',').map(x=>x.trim()),get=k=>v[head.indexOf(k)],raw=get('time'),t=Number(raw);return {t:Number.isFinite(t)?(t<1e12?t*1000:t):Date.parse(raw),o:+get('open'),h:+get('high'),l:+get('low'),c:+get('close'),v:head.includes('volume')?+get('volume'):0}}).sort((a,b)=>a.t-b.t);valid(rows);invalidate();candles=rows;source=file.name.replace(/\.csv$/i,'');isImport=true;isDemo=false;$('status').textContent='CSV · '+rows.length+' candles. Only import completed candles. Historical analysis; automatic refresh paused.';render()}catch(e){$('status').textContent=e.message}e.target.value=''};
function saveJournal(){try{localStorage.setItem('signal-journal',JSON.stringify(journal))}catch{$('status').textContent='Browser storage unavailable. Export your journal before closing.'}entries()}
function entries(){$('entries').replaceChildren();if(!journal.length){$('entries').textContent='No setups saved yet. Your next decision starts here.';return}journal.slice().reverse().forEach(j=>{let d=document.createElement('div');d.className='entry';let summary=document.createElement('span');summary.textContent=new Date(j.time).toLocaleString()+' · '+j.market+' · '+j.side+' · '+j.mode+' · close '+fmt(j.close);let input=document.createElement('input');input.placeholder='Outcome / notes';input.value=j.note||'';input.setAttribute('aria-label','Trade outcome or notes');input.onchange=()=>{j.note=input.value;saveJournal()};let del=document.createElement('button');del.className='secondary';del.textContent='Delete';del.onclick=()=>{journal=journal.filter(x=>x.id!==j.id);saveJournal()};d.append(summary,input,del);$('entries').append(d)})}
$('log').onclick=()=>{if(!setup?.plan){$('status').textContent='Load candles and enter valid risk settings first.';return}journal.push({id:crypto.randomUUID(),time:new Date().toISOString(),market:source,timeframe:$('interval').value,side:setup.side,mode:isDemo?'DEMO':isImport?'CSV':'FEED',close:setup.c,candle:new Date(candles.at(-1).t).toISOString(),...setup.plan,note:''});saveJournal();$('status').textContent='Setup saved to your browser journal. No order was placed.'};$('export').onclick=()=>{let a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(journal,null,2)],{type:'application/json'}));a.href=url;a.download='signal-desk-journal.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};entries();load();setInterval(()=>{if(!isDemo&&!isImport&&!document.hidden)load()},60000);
